 if(clan)return {...sp,skills:['Charm','Consume Alcohol','Lore (Reikland)','Perception','Sleight of Hand','Stealth (Any)','Trade (Cook)',...clan.skills],talents:[['Acute Sense (Taste)'],['Night Vision'],['Resistant (Chaos)'],['Small'],clan.talents],random:1,summary:clan.summary,guidePage:32};
 const o=s.species==='Dwarf'&&s.dwarfOriginRules!==false?CREATION_GUIDE.dwarfOrigins[s.origin]:null;
