  if(s.longbeardPenalty==='resilience'&&['resilience','resolve'].some(k=>!Number.isSafeInteger(s.longbeardResources?.[k])||s.longbeardResources[k]<1))issues.push('운명점 0 예외: 차감 전 회복력·결의를 각각 1 이상으로 기록하세요.');
