  const d=derived(s);s.longbeardPenalty=d.fate===0?'resilience':'fate';s.longbeard=true;
  s.longbeardOverrideDelta={};if(s.longbeardPenalty==='fate')for(const k of ['fate','fortune'])if(s.pointOverrides?.[k]!==undefined){const old=s.pointOverrides[k];s.pointOverrides[k]=Math.max(0,old-1);s.longbeardOverrideDelta[k]=old-s.pointOverrides[k];}
  if(!s.profile.age||Number(s.profile.age)<120)s.profile.age='120';
