function talentInfo(r,key){let k=canonical(key),b=base(k),t=r.talents[k]||Object.values(r.talents).find(t=>base(t.name)===b);return b==='Riposte'&&t?{...t,repeat:99,cap:'Agility bonus',tests:'Melee when defending',ruleOverride:'4판 반격 · 사용자 지정',text:'최대 등급은 민첩성 보너스입니다. 근접전투 기술로 방어하는 판정에 성공하면 등급당 +1 SL을 얻습니다. 빠름(Fast) 품질의 근접 무기로 근접 방어 대항에 이기면, 추가 공격 판정 없이 무기 피해에 방어 SL − 공격 SL을 더해 즉시 피해를 가합니다. 명중 부위와 무기 품질에는 기존 방어 주사위를 사용하며, 상대의 강인함 보너스와 방어점(AP)으로 피해를 줄입니다. 추가 행동은 사용하지 않으며, 참가자 한 명의 행동 차례마다 반격 등급만큼 발동할 수 있으며, 다음 참가자의 차례에 횟수가 회복됩니다. 회피 방어로는 발동하지 않습니다.'}:t}
function selectedTalents(s){let sp=speciesProfile(s);if(!sp)return[];return [...sp.talents.flatMap((arr,i)=>arr.length===1?arr:(s.speciesChoices[i]?[s.speciesChoices[i]]:[])),...s.randomTalents.map(t=>t.name),...(s.startingTalent?[s.startingTalent]:[]),...Object.keys(s.boughtTalents),...(s.species==='Wood Elf'&&s.woodKindred==='youngblood'?['Youngblood']:[])].map(t=>resolve(s,t))}
