function initialSkills(s){let map={};let sp=speciesProfile(s);if(!sp)return map;for(let l of sp.languages)map[canonical(`Language (${l})`)]=6;for(let x of s.speciesSkills){let k=resolve(s,x);map[k]=(map[k]||0)+1}for(let [k,n] of Object.entries(careerSkillRanks(s)))map[k]=(map[k]||0)+n;return map}
function skillRanks(s){let map=initialSkills(s);for(let [k,n] of Object.entries(s.skillAdv))map[k]=(map[k]||0)+n;return map}
const STAT_TALENTS={WS:'Warrior Born',BS:'Marksman',S:'Very Strong',T:'Very Resilient',I:'Sharp',Ag:'Lightning Reflexes',Dex:'Nimble-fingered',Int:'Savvy',WP:'Coolheaded',Fel:'Suave'};
function statBreakdown(s,key){const i=STATS.indexOf(key),sp=speciesProfile(s);if(i<0||!sp)return {initial:0,raw:0,ordinary:0,talent:0,xp:0,total:0};const initial=sp.mod[i]+(s.statsMode==='point'?s.points[i]:(s.rolls[s.order[i]]||0))+s.bonus[i],raw=initial+5*(s.statAdv[key]||0),ordinary=Math.min(100,raw),talent=has(s,STAT_TALENTS[key])?5:0;return {initial,raw,ordinary,talent,xp:ordinary-Math.min(100,initial),total:ordinary+talent};}
function statGain(s,key){return Math.max(0,Math.min(5,100-statBreakdown(s,key).ordinary));}
function characteristics(s){return STATS.map(k=>statBreakdown(s,k).total)}
function derived(s){let v=characteristics(s),[sb,tb,wpb]=[Math.floor(v[2]/10),Math.floor(v[3]/10),Math.floor(v[8]/10)],sp=speciesProfile(s);let strong=rank(s,'Strong Back');return guideDerived(s,{wounds:sb+wpb+(has(s,'Hardy')?3:2)*tb,enc:(has(s,'Sturdy')?2*sb+tb:s.species==='Dwarf'?2*(sb+tb):sb+tb)+(strong===1?1:strong>=2?3:0),fate:s.pointOverrides?.fate??((sp?.fate||0)+(s.finalized&&s.speciesRolls.length===1&&s.speciesRolls[0].name===s.species&&s.careerReward===2&&s.statsMode==='first'?1:0)),fortune:s.pointOverrides?.fortune??((sp?.fortune||0)+(s.speciesRolls.length===1&&s.speciesRolls[0].name===s.species?1:0)+rank(s,'Luck')),movement:(sp?.m||0)+(has(s,'Fleet-footed')?1:0)})}
function bonusBudget(s){return s.statsMode==='first'?6:s.statsMode==='reorder'?3:0}
function validate(r,s){let issues=guideIssues(r,s);let sp=speciesProfile(s),c=career(r,s);if(!sp)issues.push('종족을 선택하세요.');if(!c)issues.push('커리어를 선택하세요.');if(!s.statsMode)issues.push('능력치를 생성하세요.');if(s.statsMode==='point'&&s.points.reduce((a,b)=>a+b,0)!==100)issues.push('능력치 포인트를 총 100점으로 배분하세요.');if(s.bonus.reduce((a,b)=>a+b,0)>bonusBudget(s))issues.push('능력치 보너스 배분량을 초과했습니다.');if(s.speciesSkills.length!==5)issues.push('서로 다른 종족 기술 5개를 선택하세요.');if(Object.values(s.careerSkills).reduce((a,b)=>a+b,0)!==8)issues.push('커리어 기술 성장 8회를 배분하세요.');if(sp){sp.talents.forEach((arr,i)=>{if(arr.length>1&&!s.speciesChoices[i])issues.push('종족 재능의 선택 항목을 모두 결정하세요.')});if(s.randomTalents.length!==sp.random)issues.push('무작위 종족 재능을 굴리세요.')}if(!s.startingTalent)issues.push('시작 커리어 재능 하나를 선택하세요.');if(s.randomTalents.some(t=>t.name==='Artistic'&&!s.specials.Artistic))issues.push('예술적 재능의 예술 분야를 선택하세요.');if(s.bonusGear.length!==s.careerReward)issues.push(`무작위 커리어 보상 장비 ${s.careerReward}개를 선택하세요.`);for(let x of [...s.speciesSkills,...Object.keys(s.careerSkills)])if(needsSpecial(x)&&!s.specials[x])issues.push(`${x}의 전문 분야를 선택하세요.`);if(c){for(let t of [...CLASS_GEAR[c.class],...c.levels[0].trappings,...s.bonusGear])if(templateChoices(t).length>1&&!s.gearChoices?.[t])issues.push(t+'의 시작 장비를 선택하세요.');}if(s.wealth===null)issues.push('시작 재산을 굴리세요.');return [...new Set(issues)]}
function templateChoices(x){let depth=0,start=0,res=[];for(let i=0;i<x.length;i++){if(x[i]==='(')depth++;if(x[i]===')')depth--;if(depth===0&&x.slice(i,i+4)===' or '){res.push(x.slice(start,i));start=i+4;i+=3}}res.push(x.slice(start));return res}
function needsSpecial(x){return templateChoices(x).length>1||/\([^)]*(?:any|Any| or |as Trade)/.test(x)}
function die(n=10){return 1+Math.floor(Math.random()*n)}
function roll(n=2){return Array.from({length:n},()=>die()).reduce((a,b)=>a+b,0)}
function getSpeciesRoll(n){return n<=90?'Human':n<=94?'Halfling':n<=98?'Dwarf':n===99?'High Elf':'Wood Elf'}
function careerOptionsFromRoll(r,sp,n,origin=null){let origins=r.origins?.[sp];if(origins){let o=origins.find(o=>o.id===origin);if(!o)return [];return [...new Set(o.table.filter(x=>x.range[0]<=n&&x.range[1]>=n).map(x=>x.career))].map(id=>r.careers.find(c=>c.id===id)).filter(Boolean)}return r.careers.filter(c=>c.ranges[sp]&&c.ranges[sp][0]<=n&&c.ranges[sp][1]>=n)}
function careerFromRoll(r,sp,n,origin=null){return careerOptionsFromRoll(r,sp,n,origin)[0]}
function availableStats(r,s){let c=career(r,s);return c?Object.entries(c.advance).filter(([k,l])=>l<=s.level).map(([k])=>k):[]}
function availableSkills(r,s){let c=career(r,s);return c?[...new Set(c.levels.slice(0,s.level).flatMap(l=>l.skills))]:[]}
function availableTalents(r,s){let c=career(r,s);return c?[...new Set(c.levels.slice(0,s.level).flatMap(l=>l.talents))]:[]}
function keyForConflict(x){return canonical(x)}
function talentConflict(s,x,r=null){let b=base(x),ts=selectedTalents(s).map(base),magic=['Arcane Magic','Chaos Magic','Petty Magic','Witch!'],divine=['Bless','Invoke'];let channel=Object.keys(skillRanks(s)).some(k=>base(k)==='Channelling'&&skillRanks(s)[k]>0);if(b==='Magic Resistance'&&(channel||ts.some(k=>magic.includes(k)||divine.includes(k))))return' 마법 저항은 마법·신성 재능 및 마력 집중과 함께 습득할 수 없습니다.';if((magic.includes(b)||divine.includes(b))&&ts.includes('Magic Resistance'))return'마법 저항과 함께 습득할 수 없습니다.';if(['Bless','Invoke','Chaos Magic'].includes(b)&&selectedTalents(s).some(t=>base(t)===b&&t!==keyForConflict(x)))return'동일 계열의 다른 신 또는 학파는 GM의 별도 허가가 필요합니다.';if(b==='Arcane Magic'){let lore=x.match(/\((.*?)\)/)?.[1],known=magicLores(s),dark=['Daemonology','Necromancy'];if(known.length&&!known.includes(lore)&&!dark.includes(lore)){if(!s.species?.includes('Elf'))return '인간은 원칙적으로 한 비전 학파만 습득합니다.';if(known.length>=Math.floor(characteristics(s)[8]/10))return '비전 학파 수는 의지 보너스를 넘을 수 없습니다.';if(!known.every(k=>(s.knownSpells||[]).filter(id=>(r?.spells.find(sp=>sp.id===id)?.lore||s.history.find(h=>h.spellId===id)?.lore)===k).length>=8))return '이전 학파에서 주문 8개 이상을 먼저 배워야 합니다.';}}if(divine.includes(b)&&(channel||ts.some(k=>magic.includes(k))))return'축복·기적은 마력 집중 및 마법 재능과 함께 습득할 수 없습니다.';if(magic.includes(b)&&ts.some(k=>divine.includes(k)))return'축복·기적 재능과 함께 습득할 수 없습니다.';return''}
function canChannel(s){return !selectedTalents(s).some(t=>['Magic Resistance','Bless','Invoke'].includes(base(t)))}
function canTalent(r,s,key){if(base(key)==='Dragon Song'&&(s.species!=='High Elf'||s.career!=='elf-dragon-prince'))return false;let t=talentInfo(r,key);if(!t)return false;if(base(key)==='Savant'){let spec=key.match(/\((.*?)\)/)?.[1];if(!spec||!(skillRanks(s)['Lore ('+spec+')']>0))return false}if(t.species&&!t.species.includes(s.species))return false;if(base(key)==='High Magic'&&(!has(s,'Blessed by Isha')||!(skillRanks(s)['Channelling (Qhaysh)']>0)))return false;let n=rank(s,key);if(['Rune Magic','Master Rune Magic','Ancestral Grudge'].includes(base(key)))n=talentTotal(s,base(key));return n<talentLimit(t,s)&&!talentConflict(s,key,r)}
function matchesTemplate(template,key){template=canonical(template);key=canonical(key);let choices=templateChoices(template);if(choices.length>1)return choices.some(t=>matchesTemplate(t,key));if(template===key)return true;if(['Rune Magic','Master Rune Magic'].includes(base(template))&&base(template)===base(key))return runeTemplateMatches(template,key);if(base(template)!==base(key))return false;let inner=template.match(/\((.*?)\)/)?.[1],picked=key.match(/\((.*?)\)/)?.[1];if(!inner||!picked)return false;if(/any|Any|as Trade|All/.test(inner))return !(base(key)==='Channelling'&&inner==='Any Colour'&&picked==='Qhaysh');if(/ or /.test(inner))return inner.split(/,\s*(?:or\s+)?|\s+or\s+/).some(x=>x===picked);return false}
function advancementCost(r,s,type,key){if(type==='stat'&&statGain(s,key)===0)return null;if(type==='talent')return 100;if(type==='skill'&&base(key)==='Channelling')return (skillRanks(s)[key]||0)>=15?null:100;let n=type==='stat'?s.statAdv[key]||0:skillRanks(s)[key]||0;if(type==='skill'&&base(key)==='Language'&&key!=='Language (Magick)'&&has(s,'Linguistics'))return 50;let cost=COSTS[type]?.[n];if(cost===undefined)return null;let inside=type==='stat'?availableStats(r,s).includes(key):availableSkills(r,s).some(x=>matchesTemplate(x,key)||resolve(s,x)===key);
 if(type==='skill'&&(base(key)==='Art'&&has(s,'Artistic')||base(key)==='Trade'&&selectedTalents(s).some(t=>base(t)==='Craftsman'&&t.slice(t.indexOf('('))===key.slice(key.indexOf('(')))))inside=true;
 return cost*(inside?1:2)}
function buy(r,s,type,key){if(!s.finalized)throw Error('캐릭터 생성을 먼저 완료하세요.');let cost=advancementCost(r,s,type,key);if(cost===null)throw Error(type==='stat'&&statGain(s,key)===0?'재능 보너스를 제외한 능력치가 상한 100에 도달했습니다.':'PDF 표에 명시된 최대 성장 구간(+75)에 도달했습니다.');if(s.xp<cost)throw Error('경험치가 부족합니다.');if(type==='talent'&&['Rune Magic','Master Rune Magic'].includes(base(key))&&!runeRules.some(r=>[r['Rune Name'],r['Rune Name']+' #'+r.No].includes(key.match(/\((.*)\)/)?.[1])))throw Error('습득할 룬을 먼저 선택하세요.');if(type==='talent'&&!availableTalents(r,s).some(t=>matchesTemplate(t,key)))throw Error('현재 커리어에서 배울 수 없는 재능입니다.');if(type==='talent'&&!canTalent(r,s,key))throw Error(talentConflict(s,key,r)||'이 재능은 더 습득할 수 없습니다.');if(type==='skill'){if(key==='Channelling (Qhaysh)'&&(s.species!=='High Elf'||WINDS.some(w=>(skillRanks(s)['Channelling ('+w+')']||0)<(skillRanks(s)[key]||0)+1)))throw Error('콰이쉬는 여덟 마법 바람 각각의 성장 횟수를 넘을 수 없습니다.');if(base(key)==='Runesmithing'&&s.species!=='Dwarf')throw Error('룬스미싱은 드워프 전용 기술입니다.');if(base(key)==='Channelling'&&!canChannel(s))throw Error('보유 재능 때문에 마력 집중을 배울 수 없습니다.');let inside=availableSkills(r,s).some(x=>matchesTemplate(x,key)||resolve(s,x)===key);let info=skillInfo(r,key);if(!inside&&!info?.basic&&!(s.species==='High Elf'&&base(key)==='Channelling'&&WINDS.includes(key.match(/\((.*?)\)/)?.[1])&&has(s,'High Magic'))&&!(base(key)==='Trade'&&selectedTalents(s).some(t=>base(t)==='Craftsman'&&t.slice(t.indexOf('('))===key.slice(key.indexOf('(')))))throw Error('커리어 밖 고급 기술은 훈련 활동과 GM의 허가가 필요합니다.');}
 let gain=type==='stat'?statGain(s,key):5;s.xp-=cost;let map=type==='stat'?s.statAdv:type==='skill'?s.skillAdv:s.boughtTalents;map[key]=(map[key]||0)+1;if(type==='talent')initializeMagicGrants(s);let inCareer=type==='stat'?availableStats(r,s).includes(key):type==='skill'?availableSkills(r,s).some(x=>matchesTemplate(x,key)||resolve(s,x)===key):availableTalents(r,s).some(x=>base(x)===base(key));if(inCareer)s.tracker++;s.history.push({kind:type,key,cost,amount:gain,trackerDelta:inCareer?1:0,career:s.career,level:s.level,at:new Date().toISOString()});return cost}
function promotionNeed(s){return [0,10,12,14,16][s.level]||0}
function maxLevel(r,s){return career(r,s)?.levels.length||4}
function promote(s,r=null){let need=promotionNeed(s);if(s.level>=(r?maxLevel(r,s):4))throw Error('최종 커리어 단계입니다.');if(s.tracker<need)throw Error(`성장 추적 칸 ${need}개가 필요합니다.`);if(s.xp<100)throw Error('100 XP가 필요합니다.');s.xp-=100;s.tracker-=need;s.level++;s.history.push({trackerSpent:need,trackerCarried:s.tracker,kind:'promote',key:String(s.level),cost:100,at:new Date().toISOString()})}
function validateImport(r,s){if(s?.difficulty===4)s.difficulty=3;if(s)validateGuideState(s);if(s?.pointOverrides!==undefined&&(typeof s.pointOverrides!=='object'||s.pointOverrides===null||Array.isArray(s.pointOverrides)||Object.entries(s.pointOverrides).some(([k,v])=>!['fate','fortune'].includes(k)||!Number.isSafeInteger(v)||v<0)))throw Error('운명점·행운점 기록이 잘못되었습니다.');if(s&&s.difficulty===undefined)s.difficulty=1;if(!s||!DIFFICULTIES.some(d=>d.id===s.difficulty))throw Error('시작 난이도가 잘못되었습니다.');if(!s||s.version!==1||!Object.keys(SPECIES).includes(s.species)||!r.careers.some(c=>c.id===s.career&&careerAllowed(r,s,c)))throw Error('지원되는 캐릭터 파일이 아닙니다.');if(!Number.isInteger(s.level)||s.level<1||s.level>maxLevel(r,s))throw Error('커리어 단계가 잘못되었습니다.');for(let k of ['points','rolls','order','bonus','speciesSkills','randomTalents','bonusGear','extraGear','history'])if(!Array.isArray(s[k]))throw Error('캐릭터 데이터가 누락되었습니다.');for(let k of ['xp','xpEarned','tracker'])if(!Number.isFinite(s[k])||s[k]<0)throw Error('경험치 또는 추적 값이 잘못되었습니다.');if(s.points.length!==10||s.points.some(n=>!Number.isInteger(n)||n<4||n>16)||s.bonus.length!==10||s.bonus.some(n=>!Number.isInteger(n)||n<0)||s.order.length!==10||new Set(s.order).size!==10||s.order.some(n=>!Number.isInteger(n)||n<0||n>9))throw Error('능력치 데이터가 잘못되었습니다.');for(let k of ['careerSkills','specials','speciesChoices','statAdv','skillAdv','boughtTalents','profile','gearChoices']){if(!s[k]||typeof s[k]!=='object'||Array.isArray(s[k]))throw Error('캐릭터 세부 데이터가 잘못되었습니다.');for(let [key,v] of Object.entries(s[k])){if(['__proto__','constructor','prototype'].includes(key))throw Error('잘못된 데이터입니다.');if(k.endsWith('Adv')||['careerSkills','boughtTalents'].includes(k)){if(!Number.isInteger(v)||v<0||v>100)throw Error('성장 횟수가 잘못되었습니다.')}else if(typeof v!=='string'||v.length>20000)throw Error('텍스트 데이터가 잘못되었습니다.')}}if(s.goldPennies===undefined){s.goldPennies=0;s.goldInitialized=false;s.purchases=[];s.moneyHistory=[];}if(s.sheetNotes===undefined)s.sheetNotes={};if(!Number.isSafeInteger(s.goldPennies)||s.goldPennies<0||typeof s.goldInitialized!=='boolean'||!Array.isArray(s.purchases)||!Array.isArray(s.moneyHistory)||!s.sheetNotes||typeof s.sheetNotes!=='object'||Array.isArray(s.sheetNotes))throw Error('골드 또는 소지품 데이터가 잘못되었습니다.');for(let p of s.purchases)if(!p||typeof p.id!=='string'||!Number.isInteger(p.quantity)||p.quantity<1||p.quantity>999||!Number.isSafeInteger(p.unitPricePennies)||p.unitPricePennies<=0||!['인간','엘프','드워프'].includes(p.zone))throw Error('구매 기록이 잘못되었습니다.');for(let h of s.moneyHistory)if(!h||!['grant','purchase','magic-craft'].includes(h.kind)||!Number.isSafeInteger(h.amount)||h.kind==='grant'&&h.amount<=0||h.kind==='purchase'&&(h.amount>=0||typeof h.item!=='string'||!Number.isInteger(h.quantity)||h.quantity<1||!['인간','엘프','드워프'].includes(h.zone)))throw Error('골드 거래 기록이 잘못되었습니다.');for(let h of s.moneyHistory)if(h.kind==='magic-craft'&&(h.amount>0||typeof h.item!=='string'||typeof h.project!=='string'))throw Error('마법 제작 지출 기록이 잘못되었습니다.');for(let [k,v] of Object.entries(s.sheetNotes))if(['__proto__','constructor','prototype'].includes(k)||typeof v!=='string'||v.length>20000)throw Error('시트 메모가 잘못되었습니다.');MOUNTS.validate(s);if(s.finalized)initMoney(r,s);migrateExtension(r,s);Q.ensure(s);characterId(s);return s}

const WINDS=['Aqshy','Azyr','Chamon','Ghur','Ghyran','Hysh','Shyish','Ulgu'];
function talentTotal(s,b){return [...new Set(selectedTalents(s))].filter(t=>base(t)===b).reduce((a,k)=>a+rank(s,k),0)}
function talentLimit(t,s){if(base(t.name)==='Riposte')return Math.floor(characteristics(s)[5]/10);if(!t.cap)return t.repeat===99?1:t.repeat;let v=characteristics(s),map={'Weapon Skill':0,'Ballistic Skill':1,'Strength':2,'Toughness':3,'Initiative':4,'Agility':5,'Dexterity':6,'Intelligence':7,'Willpower':8,'Fellowship':9};return t.cap.split(' + ').reduce((a,x)=>a+(/^\d+$/.test(x)?Number(x):Math.floor(v[map[x.replace(/ bonus/i,'')]]/10)||0),0)}
const RUNE_FORMS={'Weapon Runes':'무기 룬','Armour Runes':'방어구 룬','Talismanic Runes':'탈리스만 룬','Protection Runes':'보호 룬','Protective Runes':'보호 룬','Engineering Runes':'공학 룬'};
let runeRules=[];
function configureRunes(rows){runeRules=rows}
function runeTemplateMatches(template,key){let b=base(key),name=key.match(/\((.*)\)/)?.[1],r=runeRules.find(x=>name===x['Rune Name']+' #'+x.No||name===x['Rune Name']);if(!r||b!==base(template)||(b==='Master Rune Magic')!==(r['종류']==='마스터'))return false;let form=template.match(/\((.*)\)/)?.[1];if(!form||/All Forms|Any/i.test(form))return r['분류']!=='파멸 룬';if(form===r['Rune Name']||form===name)return true;return Object.entries(RUNE_FORMS).some(([en,ko])=>form.includes(en)&&r['분류']===ko)}
function learnedRunes(s){
 let ids=[...new Set(selectedTalents(s))].filter(t=>['Rune Magic','Master Rune Magic'].includes(base(t))).map(t=>runeRules.find(r=>[r['Rune Name'],r['Rune Name']+' #'+r.No].includes(t.match(/\((.*)\)/)?.[1]))?.No).filter(Boolean);
 ids.push(...(s.runeRecipes||[]));if(has(s,'Master Rune Magic')||ids.some(n=>runeRules.find(r=>r.No===n)?.['종류']==='마스터'))ids.push(...runeRules.filter(r=>r['분류']==='파멸 룬').map(r=>r.No));return [...new Set(ids)];
}
function learnRune(r,s,no){let rune=runeRules.find(x=>x.No===no);if(!rune||rune['분류']==='파멸 룬')throw Error('선택할 수 없는 룬입니다.');if(learnedRunes(s).includes(no))throw Error('이미 알고 있는 룬입니다.');return buy(r,s,( 'talent'),(rune['종류']==='마스터'?'Master Rune Magic':'Rune Magic')+' ('+rune['Rune Name']+' #'+rune.No+')')}
let runeItemResolver=null;
function configureRuneItemResolver(resolver){runeItemResolver=resolver}
function checkRuneItem(s,itemKey,rune){if(s.customItems?.some(i=>i.id===itemKey&&i.magicalArtifact))throw Error('마법 유물에는 새 드워프 룬을 각인할 수 없습니다.');if(runeItemResolver){let row=runeItemResolver(s,itemKey);if(!row||!row.runeForms.includes(rune['분류']))throw Error('이 아이템 종류에는 해당 룬을 각인할 수 없습니다.');}let current=s.runeItems[itemKey]||[],pending=s.runeProjects.filter(p=>p.itemKey===itemKey&&!p.completed).map(p=>p.rune);if(current.length+pending.length>=3)throw Error('한 아이템에는 최대 3개의 룬만 새길 수 있습니다.');if(rune['종류']==='마스터'&&[...current,...pending].some(n=>runeRules.find(r=>r.No===n)?.['종류']==='마스터'))throw Error('한 아이템에는 마스터 룬을 하나만 새길 수 있습니다.');if(rune['분류']==='파멸 룬')throw Error('파멸 룬은 파멸의 모루에서 행동으로 발동합니다.');}
