function startRuneProject(s,itemKey,no){let rune=runeRules.find(r=>r.No===no);if(s.species!=='Dwarf'||!learnedRunes(s).includes(no)||!(skillRanks(s).Runesmithing>0))throw Error('드워프 룬스미싱 기술과 해당 룬 지식이 필요합니다.');if(!rune)throw Error('룬을 찾지 못했습니다.');checkRuneItem(s,itemKey,rune);let target=Number(rune['필요 SL']);if(!Number.isFinite(target)||target<=0)throw Error('연장 판정으로 제작하는 룬이 아닙니다.');s.runeProjects.push({id:'project-'+Date.now()+'-'+Math.random().toString(36).slice(2),itemKey,rune:no,target,sl:0,tests:[],completed:false});}
