function magicLores(s){return [...new Set(selectedTalents(s).filter(t=>['Arcane Magic','Chaos Magic'].includes(base(t))).map(t=>t.match(/\((.*?)\)/)?.[1]).filter(Boolean))]}
function initializeMagicGrants(s){s.spellGrants||={};if(has(s,'Petty Magic')&&s.spellGrants.Petty===undefined)s.spellGrants.Petty=Math.max(0,Math.floor(characteristics(s)[8]/10));for(let lore of magicLores(s))if(s.spellGrants[lore]===undefined)s.spellGrants[lore]=1;if(has(s,'Witch!')&&s.spellGrants.Witch===undefined)s.spellGrants.Witch=1;}
function spellCategory(sp){return sp?.category||(sp?.lore==='Elven Arcane'?'petty':'high')}
