function highSpellCost(r,s){let count=s.knownSpells.filter(id=>spellCategory(r.spells.find(x=>x.id===id))==='high').length,b=Math.max(1,Math.floor(characteristics(s)[7]/10));return 200*Math.max(1,Math.ceil(count/b))}
