function castHighMagic(r,s,id,{sl,overcast=0,armour=0,staff=false,burnRoll=100}){let spell=r.spells.find(x=>x.id===id);if(s.species!=='High Elf'||!has(s,'High Magic')||!s.knownSpells.includes(id)||s.burnout)throw Error('암기한 하이 매직 주문과 시전 가능한 상태가 필요합니다.');if([sl,overcast,armour,burnRoll].some(n=>!Number.isInteger(n))||overcast<0||armour<0||burnRoll<1||burnRoll>100)throw Error('판정 입력이 잘못되었습니다.');let cn=Math.max(0,spell.cn-(staff?1:0)),effective=sl-armour,success=effective>=cn,available=Math.max(0,effective-cn+rank(s,'High Magic'));if(overcast>available||!success&&overcast)throw Error('사용 가능한 과잉 시전 SL을 넘었습니다.');let chance=success?Math.max(0,overcast-Math.floor(characteristics(s)[8]/10)):0,burned=chance>0&&burnRoll<=chance,permanent=burned&&(burnRoll===100||burnRoll%11===0);if(burned)s.burnout={days:burnRoll,permanent};let result={spell:id,sl,effective,cn,success,overcast,chance,burnRoll,burned,permanent,at:new Date().toISOString()};s.magicLog.push(result);return result}
