function supplementalItem(english,name,category,sub,enc,stats,qualities='',effect='',reference='기존 아이템 표의 유사 장비를 기준으로 보완'){
 let item={id:'supp-'+english.toLowerCase().replace(/[^a-z0-9]+/g,'-'),english,name,category,zones:[],pricePennies:null,supplemental:true,fields:{'한글명':name,'원문명':english,'대분류':category,'하위분류':sub,'Enc/운반':String(enc),'핵심 수치':stats,'품질/특성':qualities,'효과/규칙 요약':effect,'스펙 출처':'보완 스펙 · '+reference,'구매가능':'시작/소지 장비의 스펙 보완','상점판매':'기존 상점 목록 유지'}};
 SUPPLEMENTAL_ITEMS.push(item);return item;
}
