function resolveItemSpec(text){
 if(/^Gromril /.test(String(text))&&GUIDE_ALIASES[text])return ITEMS.find(i=>i.english===GUIDE_ALIASES[text]&&i.fields['하위분류'].includes('그롬릴'));let clean=String(text).trim().replace(/^\(2H\)\s*/,'').replace(/^\d+\s+(?:Sets? of |sets? of )?/i,'').replace(/^Two /,'').replace(/^Quality /,'');
 if(String(text)==='Dwarf Hammer')return ITEMS.find(i=>i.english==='Dwarf Warhammer');let exact=SUPPLEMENTAL_ITEMS.find(i=>i.english.toLowerCase()===String(text).toLowerCase());if(exact)return exact;
 let alias={'Longbow and 10 arrows':'Longbow','Personally crafted Elf Bow and 10 arrows':'Elf Bow','Elf Bow with at least 1 Quality':'Elf Bow','Hand Weapon (Pick)':'Pick','Great Weapon (Two-handed Pick)':'Two-handed Pick','Great Weapon (Military Flail)':'Military Flail','Dwarf Hammer':'Dwarf Warhammer','Dwarf Throwing Axe':'Dwarf Throwing Axes','Two Chainaxes':'Chainaxe','Two Runic Chainaxes':'Chainaxe','Book (Engineer)':'Book, Engineer','Plate Helm (Open)':'Open Helm','Tall Helmet':'Helmet','Tall Sea Helm':'Helmet','Miner’s Helm':'Miner’s Helm (Open)','Open Helm (Miner’s Helm)':'Miner’s Helm (Open)','Hand Weapon (Dwarf Axe)':'Dwarf Axe','Great Weapon (Dwarf Greataxe)':'Dwarf Greataxe','Hand Weapon (Sword)':'Sword','Hand Weapon (Axe)':'Hand Weapon','Hand Weapon (Sickle)':'Hand Weapon','Hand Weapon (Boat Hook)':'Hand Weapon','Dwarf Crossbow and Ammunition':'Dwarf Crossbow','Dwarf Handgun and Ammunition':'Dwarf Handgun','Elf Bow and 10 Arrows':'Elf Bow','Elf Bow and 10 Barbed Arrows':'Elf Bow','Runic Axe':'Dwarf Axe','Rune Axe':'Dwarf Axe','Runic Hammer':'Dwarf Hammer','Runic Shield 65':'Shield','Runic Armour':'Plate Armour','Oath Stone':'Oathstone','Skycutter Chariot and Swiftfeather Roc':'Skycutter'};
 if(/^Book \((.*?)\)$/.test(clean))clean='Book, '+clean.match(/^Book \((.*?)\)$/)[1];if(/^Trade Tools \(/.test(clean)){let item={...ITEMS.find(i=>i.english==='Trade Tools'),english:String(text)};if(item.fields)return {...item,fields:{...item.fields,'Enc/운반':'1','가격/가치':'3 GC','스펙 출처':'5판 코어 룰북 312쪽'}};}clean=GUIDE_ALIASES[clean]||alias[clean]||clean.replace(/ with \d+ (Arrows|Bolts|Shots|Bullets).*$/i,'');
 let base=SUPPLEMENTAL_ITEMS.find(i=>i.english.toLowerCase()===clean.toLowerCase())||ITEMS.find(i=>i.english.replace(/^\(2H\)\s*/,'').toLowerCase()===clean.toLowerCase());
 if(base)return {...base,name:base.name,english:String(text)};
 if(/Cloth|Clothes|Robes|Garb|Attire|Cloak|Uniform|Livery|Coat|Boots|Hat|Face Wrap|Scarves|Mask/i.test(clean))return {...SUPPLEMENTAL_ITEMS.find(i=>i.english==='Clothing'),english:String(text),name:String(text)};
 // Noncombat belongings still have an automatic type and usage record.
 return {id:'personal-'+String(text).toLowerCase().replace(/[^a-z0-9]+/g,'-'),english:String(text),name:String(text),category:'기타 소지품',zones:[],pricePennies:null,supplemental:true,fields:{'하위분류':'기타','Enc/운반':'—','핵심 수치':'-','효과/규칙 요약':'소지품 기록 · 전투 수치 없음','스펙 출처':'소지품 분류'}};
}
function runeFormsFor(item){
 if(!item||item.magicalArtifact)return [];if(item.craftType)return CRAFT_TYPES[item.craftType]?.[3]?[CRAFT_TYPES[item.craftType][3]]:[];let en=item.english,sub=item.fields['하위분류']||'';
 if(/Enchanted|Magical/i.test(en)||item.category==='마법무기/유물')return [];
 if(item.category==='무기')return sub.includes('근접')&&!/Quarterstaff|Wooden|Whip|Garrote/i.test(en)?['무기 룬']:[];
 if(item.category==='방어구')return /그롬릴|메일|플레이트/.test(sub)?['방어구 룬']:[];
 if(/무기\/포병|무기\/설치형/.test(item.category)&&item.fields['구역분류']==='드워프')return ['공학 룬'];
 if(/Oathstone|Battle Standard|Shield Platform|Workshop|Forge|Gate Key|Anvil|Stone Tablet/i.test(en))return /Anvil of Doom/i.test(en)?[]:['보호 룬'];
 if(/Amulet|Jewellery|Pendant|Medallion|Signet Ring|Religious Symbol|Charms|Seal of Office|Copper Badge|Keys|Ear Pick|Tweezers|Tankard|Metal Foil|Runescribing|Chisel|Hammer and|Trade Tools \((Smith|Engraver|Mason)\)/i.test(en))return ['탈리스만 룬'];
 return [];
}

