const ARMOUR_PARTS={head:'머리',body:'몸통',arms:'팔',legs:'다리'};
function armourProfile(item){
 if(item?.category!=='방어구')return {slots:[],ap:null};const stats=item.fields['핵심 수치']||'';
 const slots=[['head',/\bHead\b|머리/],['body',/\bBody\b|몸통/],['arms',/\bArms?\b|팔/],['legs',/\bLegs?\b|다리/]].filter(([k,re])=>re.test(stats)).map(([k])=>k);
 const match=stats.match(/\bAP\s+(\d+)/);return {slots,ap:match?Number(match[1]):null};
}

