const clone=x=>JSON.parse(JSON.stringify(x));
const id=()=> 'arcane-'+Date.now()+'-'+Math.random().toString(36).slice(2);
const validText=(x,max=300)=>typeof x==='string'&&x.length<=max;
function arcaneSkill(r,s,key){const info=E.skillInfo(r,key),ranks=E.skillRanks(s)[E.resolve(s,key)]||0;if(!info||!s.statsMode||!info.basic&&!ranks)return null;return E.characteristics(s)[E.STATS.indexOf(info.stat)]+ranks*5;}
function arcaneTrades(s){return Object.keys(E.skillRanks(s)).filter(k=>E.base(k)==='Trade'&&E.skillRanks(s)[k]>0&&!/any| as /i.test(k));}
function arcaneBaseEligible(item){return item?.category==='무기'&&!!E.parseWeaponDamage(item.fields?.['핵심 수치']?.match(/Damage\s*([^,]+)/i)?.[1])&&!item.magicalArtifact&&!/Magical|마법|Enchanted/i.test(item.fields?.['품질/특성']+' '+item.english)&&!/\b(?:shield|buckler)\b/i.test(item.english);}

function archiveWeaponBlueprint(base,{sbMultiplier,damage}={}){
 if(!arcaneBaseEligible(base))throw Error('일반 무기의 새 제작 설계도를 선택하세요.');
 const parsed=E.parseWeaponDamage(base.fields['핵심 수치'].match(/Damage\s*([^,;]+)/i)?.[1]);
 const mult=sbMultiplier===undefined||sbMultiplier===''?parsed.sbMultiplier:Number(sbMultiplier),flat=damage===undefined||damage===''?parsed.damage:Number(damage);
 if(![0,1,2].includes(mult)||!Number.isSafeInteger(flat)||flat<0||flat>1000)throw Error('근력 보너스 배수와 추가 피해를 확인하세요.');
 const formula=(mult?'+'+(mult===1?'SB':mult+'×SB'):'')+(mult&&flat>=0?'+':'')+flat;
 const result=clone(base);result.fields['핵심 수치']=result.fields['핵심 수치'].replace(/Damage\s*[^,;]+/i,'Damage '+formula);
 if(mult!==parsed.sbMultiplier||flat!==parsed.damage)result.fields['스펙 출처']=(base.fields['스펙 출처']||'기본 무기')+' · 사용자 지정 피해 설계';
 return result;
}

function arcaneQuote(item,abilities,{fine=false,durable=false}={}){const price=item?.pricePennies;if(!Number.isSafeInteger(price)||price<0)return null;const count=abilities.filter(k=>k!=='winds').length||1;const n=price*50*count*2**(Number(fine)+Number(durable));return Number.isSafeInteger(n)?n:null;}
function arcaneTime(p){const t=ARCANE_TYPES.find(x=>x.id===p.type);return t?.time==null?'제작자와 합의':`${t.time*(p.result?.timeMultiplier||1)}${t.unit}`;}
