 const lore=E.runeTest4e(p.loreValue,loreRoll,0,p.loreModifier),trade=E.runeTest4e(p.tradeValue,tradeRoll,0,p.tradeModifier),sl=Math.min(lore.sl,trade.sl),progress=Math.max(0,p.sl+sl);
