  const n=draw();if(!Number.isInteger(n)||n<1||n>100)throw Error('특이점 주사위는 1~100이어야 합니다.');
  const total=n+applied,q=ARCANE_QUIRKS.find(q=>total>=q.min&&total<=q.max);if(!q)throw Error('특이점 표의 범위를 벗어났습니다.');rolls.push({roll:n,offset:applied,total});
  if(!rejectEmpty||![1,3].includes(q.no)){const out={...q,rolls};if(q.no===6)out.days=draw();if(q.no===10){const sky=draw(10);if(!Number.isInteger(sky)||sky<1||sky>10)throw Error('천체 주사위는 1~10이어야 합니다.');out.sky=sky<=6?'태양':sky<=9?'만슬리프':'모르슬리프';}return out;}applied=40;
