function validateArcaneArtifact(a){if(a===undefined)return;if(a.physicalQualities!==undefined&&(!validText(a.physicalQualities,2000)))throw Error('마법 유물 물품 품질이 잘못되었습니다.');if(!a||!validText(a.projectId)||!ARCANE_TYPES.some(t=>t.id===a.type)||!Array.isArray(a.abilities)||(!a.abilities.length&&!['staff','scroll'].includes(a.type)&&!a.legendary)||a.abilities.some(k=>!archiveAllowed(a.type,k))||new Set(a.abilities).size!==a.abilities.length||!Array.isArray(a.quirks)||a.quirks.length>100||typeof a.active!=='boolean'||typeof a.conditionsMet!=='boolean'||!Number.isSafeInteger(a.elapsedDays)||a.elapsedDays<0)throw Error('마법 유물 기록이 잘못되었습니다.');if(a.charges!==null&&a.charges!==undefined&&(!Number.isInteger(a.charges)||a.charges<0||a.charges>1000000)||a.quantity!==undefined&&(!Number.isInteger(a.quantity)||a.quantity<1||a.quantity>1000)||a.attachedTo!==undefined&&!validText(a.attachedTo,200)||a.spellId!==null&&a.spellId!==undefined&&!validText(a.spellId,300)||a.dailyUsed&&Object.entries(a.dailyUsed).some(([k,v])=>!validText(k,100)||!Number.isSafeInteger(v)||v<0||v>1000))throw Error('유물의 잔여량·주문·부착 기록이 잘못되었습니다.');if(a.version===2){if(!Array.isArray(a.rolls)||a.rolls.length>1000||a.rolls.some(t=>![10,100].includes(t.die)||!Number.isInteger(t.roll)||t.roll<1||t.roll>t.die||!validText(t.table,200))||!Array.isArray(a.history)||a.history.length>100||a.history.some(h=>!X.ARCHIVE_HISTORY.some(x=>x.id===h.id)||!validText(h.name)||!validText(h.text,2000))||a.creature!==null&&!X.ARCHIVE_CREATURES.some(c=>c.id===a.creature)||typeof a.identified!=='boolean'||a.fullSuit!==undefined&&typeof a.fullSuit!=='boolean'||a.dailyUsed&&(typeof a.dailyUsed!=='object'||Array.isArray(a.dailyUsed)))throw Error('원문 유물 생성·역사·식별 기록이 잘못되었습니다.');}for(const q of a.quirks)if(!q||!ARCANE_QUIRKS.some(x=>x.no===q.no&&x.text===q.text)||q.no===6&&(!Number.isInteger(q.days)||q.days<1||q.days>100)||q.no===10&&!['태양','만슬리프','모르슬리프'].includes(q.sky))throw Error('마법 유물 특이점 기록이 잘못되었습니다.');}
