 const signed=n=>n>=0?'+'+n:String(n);
 const state=()=>ctx.state(),rules=()=>ctx.rules();
 function members(){try{return JSON.parse(localStorage.getItem('wfrp-forge-party-v1')||'[]').map((p,i)=>p?{index:i,state:p.state}:null).filter(Boolean).filter(p=>{try{E.validateImport(rules(),JSON.parse(JSON.stringify(p.state)));return true}catch{return false}})}catch{return [];}}
 function artisan(){return draft.mode==='collaborate'?members().find(p=>String(p.index)===draft.artisan)?.state:state();}
 function prepareDefaults(){if(owner!==state()){owner=state();draft.name='';draft.sbMultiplier='';draft.damage='';draft.trade='';draft.verified=false;draft.consulted=false;draft.commissioned=false;draft.gold='';draft.abilities=['winds'];draft.design=null;}const trades=A.arcaneTrades(artisan()||E.empty());if(!trades.includes(draft.trade))draft.trade=trades[0]||'';}
 const select=(id,label,rows,value)=>`<label>${esc(label)}<select id="${id}">${rows.map(([k,text])=>`<option value="${esc(k)}" ${String(k)===String(value)?'selected':''}>${esc(text)}</option>`).join('')}</select></label>`;
 const number=(id,label,value,min=0,max=999999999)=>`<label>${esc(label)}<input id="${id}" type="number" min="${min}" max="${max}" step="1" value="${esc(value)}"></label>`;
 const check=(id,label,value)=>`<label class="arcane-check"><input id="${id}" type="checkbox" ${value?'checked':''}>${esc(label)}</label>`;

 function blueprint(){
  const base=A.archiveBases(draft.type).find(i=>i.id===draft.baseId);return draft.type==='weapon'&&base?A.archiveWeaponBlueprint(base,{sbMultiplier:draft.sbMultiplier,damage:draft.damage}):base;
 }
 function weaponDesignControls(){
  if(draft.type!=='weapon')return '';
  const base=A.archiveBases(draft.type).find(i=>i.id===draft.baseId)||A.archiveBases('weapon')[0],parsed=E.parseWeaponDamage(base?.fields['핵심 수치']?.match(/Damage\s*([^,;]+)/i)?.[1]),mult=draft.sbMultiplier===''?parsed?.sbMultiplier??1:Number(draft.sbMultiplier),flat=draft.damage===''?parsed?.damage??4:Number(draft.damage),sb=Math.floor(E.characteristics(state())[2]/10);
  return `<section class="block"><h2>마법 무기의 피해 설계</h2><div class="arcane-form-grid">${select('arcane-sbMultiplier','근력 보너스 적용',[[1,'근력 보너스 ×1'],[2,'근력 보너스 ×2'],[0,'고정 피해 · 근력 보너스 미적용']],mult)}${number('arcane-damage','추가 피해',flat,0,1000)}</div><p class="callout">근력 보너스 ${sb} × ${mult} + ${flat} = 기본 피해 ${sb*mult+flat}</p><p class="note">예: 근력 보너스 ×2, 추가 피해 10 → 2×SB+10. 선택한 기본 무기를 새 원재료부터 만드는 설계이며, 변경한 피해는 사용자 지정 설계로 기록합니다. 마법 능력의 주사위 결과는 유지됩니다.</p></section>`;
 }
 function makerPreview(){
  const maker=draft.mode==='commission'?draft.expertName||'의뢰한 전문가':draft.mode==='collaborate'?artisan()?.profile.name||'협력 장인':state().profile.name||'플레이어 캐릭터';
  return `<p class="callout arcane-name-preview">완성품 이름: ${esc(E.craftedName(draft.name||draft.design?.base.name||'아이템 이름',maker))}</p>`;
 }

 function quote(){return draft.design?A.archiveQuote(draft.design,draft):null;}
 function navigation(){return `<div class="tabs arcane-tabs">${[['prepare','새 제작 준비'],['acquire','입수 · 발견'],['identify','유물 식별'],['projects','제작 작업 · 기록'],['rules','제작 규칙 · 능력표']].map(([k,l])=>button('arcane-tab',l,`data-key="${k}"`,k===tab?'active':'')).join('')}</div>`;}
 function page(){
  prepareDefaults();const intro=`<section class="arcane-intro block"><p class="eyebrow">ARCHIVES OF THE EMPIRE · VOLUME II</p><h2>마법의 바람을 물품에 엮습니다</h2><p>마법은 제작 과정에서 물품의 구조에 스며듭니다. 새 원재료와 공예 기술을 준비하고, 위험한 제작 판정을 견뎌 영구적인 마법 유물을 완성하세요.</p><div class="arcane-steps"><span>01 · 재료와 비용</span><span>02 · 낮은 SL을 누적</span><span>03 · 완성 판정</span><span>04 · 소지품에 보관·장착</span></div><p class="note">기존 무기·갑옷에 영구 마법을 덧붙이는 방식은 사용할 수 없습니다. 룬 각인은 별도 대장간에서 진행합니다.</p></section>`;
  if(!state().finalized)return intro+`<div class="empty">캐릭터 생성을 완료한 뒤 제작을 준비할 수 있습니다.</div>`+button('nav','캐릭터 시트로','data-section="sheet"');
  return `<div class="arcane-page">${intro}${navigation()}${tab==='prepare'?prepare():tab==='acquire'?acquire():tab==='identify'?identification():tab==='projects'?projects():rulebook()}</div>`;
 }
 function prepare(){
  const base=A.archiveBases(draft.type).find(i=>i.id===draft.baseId),trades=A.arcaneTrades(artisan()||E.empty()),lore=A.arcaneSkill(rules(),state(),'Lore (Magic)'),trade=artisan()?A.arcaneSkill(rules(),artisan(),draft.trade):null,q=quote();
  return `${designPanel(draft)}${weaponDesignControls()}${makerPreview()}<section class="block"><h2>누가 제작하나요?</h2>${draft.mode==='commission'?`<div class="arcane-form-grid"><label>전문가 이름<input id="arcane-expertName" maxlength="200" value="${esc(draft.expertName)}" placeholder="GM이 확인한 실제 제작자"></label>${number('arcane-expertLore','전문가 학문(마법) 값',draft.expertLore,1,300)}${number('arcane-expertTrade','전문가 공예 값',draft.expertTrade,1,300)}</div>${check('arcane-consulted','전문가 상담 활동에 성공했습니다.',draft.consulted)}${check('arcane-commissioned','의뢰 활동에 성공하고 비용·조건에 합의했습니다.',draft.commissioned)}<p class="note">의뢰는 연장 제작 판정을 건너뛰고 완성 판정으로 진행합니다. 전문가의 능력치는 임의로 생성하지 않습니다.</p>`:`${draft.mode==='collaborate'?select('arcane-artisan','협력할 파티 장인',[['','파티원을 선택하세요'],...members().map(p=>[p.index,`파티원 ${p.index+1} · ${p.state.profile.name||'이름 없는 모험가'}`])],draft.artisan):''}<div class="arcane-form-grid">${select('arcane-trade','제작에 사용할 공예 기술',trades.length?trades.map(k=>[k,tr(k)]):[['','익힌 공예 기술이 없습니다']],draft.trade)}<div class="arcane-maker-values"><span>학문(마법) <b>${lore??'미습득'}</b></span><span>공예 <b>${trade??'미습득'}</b></span></div></div><p class="note">${draft.mode==='collaborate'?'자신은 학문(마법), 장인은 자신의 공예 기술로 판정합니다. 판정 한 번마다 두 캐릭터가 제작 활동을 각각 하나씩 소비합니다.':'두 기술 모두 자신의 실제 시트 수치를 사용합니다. 판정 한 번은 제작 활동 한 번입니다.'}</p><div class="arcane-form-grid">${select('arcane-loreModifier','학문(마법) 제작 난이도',[[-30,'매우 어려움 −30 · 기본'],[-20,'어려움 −20 · GM이 인정한 재료'],[-10,'까다로움 −10 · GM이 인정한 재료'],[0,'도전적 +0 · GM 확인'],[20,'평균 +20 · GM 확인']],draft.loreModifier)}${select('arcane-tradeModifier','공예 제작 난이도',[[20,'흔함 · 평균 +20'],[0,'희귀 · 도전적 +0'],[-10,'매우 희귀 · 까다로움 −10'],[-30,'이국적 · 매우 어려움 −30']],draft.tradeModifier)}</div><p class="note">희귀 재료로 학문(마법) 난이도를 낮추려면 GM의 확인이 필요합니다. 완성 판정에서는 두 기술 모두 보정 +0입니다.</p>`}</section><section class="block"><h2>재료 · 품질 · 비용</h2>${check('arcane-fine','고급(Fine) 품질로 제작 · 기본 물품 가격 ×2',draft.fine)}${check('arcane-durable','내구성(Durable) 품질로 제작 · 기본 물품 가격 ×2',draft.durable)}<p class="note">평판 좋은 전문가들은 두 품질을 갖춘 물품을 만듭니다. 제작자가 요구하는 재료·대가를 GM과 확인하세요.</p><div class="arcane-cost-preview"><span>표의 참고 제작비</span><strong>${q===null?'별도 합의 필요':ctx.coins(q)}</strong>${button('arcane-quote','참고 금액 입력',q===null?'disabled':'')}</div><p class="note">참고값은 원문 종류별 비용표를 적용합니다. 주문 CN 가격은 골드 단위입니다. 표에 산식이 없거나 기본 가격을 확인할 수 없으면 별도로 합의합니다. 실제 지급액은 아래에 기록합니다. 금전 이외의 대가와 필요한 재료는 확인 항목으로 처리합니다.</p><div class="arcane-form-grid">${number('arcane-gold','골드',draft.gold)}${number('arcane-silver','실버',draft.silver,0,19)}${number('arcane-pennies','페니',draft.pennies,0,11)}</div>${check('arcane-verified','새 원재료, 필요한 마법 지식, 적절한 공예 분야·도구·작업장, 지급액과 추가 대가를 GM과 확인했습니다.',draft.verified)}<p>보유 재산 <strong>${ctx.coins(state().goldPennies)}</strong> · 기본 제작 기간 <strong>${esc(A.arcaneTime({type:draft.type}))}</strong></p><div class="footer-actions">${button('arcane-start','제작 작업 시작 · 비용 지급','','primary')}</div></section>`;
 }
 function roll(t,label){return `<div class="arcane-roll"><span>${label}</span><strong>D100 ${String(t.roll).padStart(2,'0')}</strong><small>${t.target} 이하 · ${t.success?'성공':'실패'}</small><b>${signed(t.sl)} SL</b></div>`;}
 function projects(){
  const list=state().magicCraftProjects||[];
  return `<div class="arcane-projects">${list.length?list.slice().reverse().map(p=>{
   const labels={crafting:'제작 중',ready:'완성 판정 준비', 'awaiting-zero':'0 SL 결과 확인',completed:'완성',failed:'제작 실패',explosion:'마법 폭발',cancelled:'중단'},r=p.result;
   return `<article class="block arcane-project arcane-${p.status}" data-arcane-project="${esc(p.id)}"><div class="block-title"><h2>${esc(p.name)}</h2><span class="pill">${labels[p.status]}</span></div><p>${esc(p.maker)}${p.mode==='collaborate'?' + '+esc(p.artisanName):''} · ${p.mode==='commission'?'전문가 의뢰':p.mode==='collaborate'?'협력 제작':'직접 제작'} · ${ctx.coins(p.costPennies)}</p><p class="note">${esc(p.base.name)} · ${p.abilities.map(k=>esc(A.ARCANE_ABILITIES.find(a=>a.id===k)?.name)).join(' · ')}</p>${p.mode==='commission'?'':`<div class="arcane-progress-label"><strong>${p.sl} / 20 SL</strong><span>제작 판정 ${p.attempts.length}회</span></div><div class="meter"><div style="width:${Math.min(100,p.sl*5)}%"></div></div>`}${p.status==='crafting'?`<p>학문 ${p.loreValue}${signed(p.loreModifier)} · 공예 ${p.tradeValue}${signed(p.tradeModifier)}</p>${button('arcane-roll','제작 활동 · 두 기술 판정',`data-key="${esc(p.id)}"`,'primary')}`:''}${p.attempts.length?`<div class="arcane-last-roll">${roll(p.attempts.at(-1).lore,'학문(마법)')}${roll(p.attempts.at(-1).trade,'공예')}<p>낮은 결과 <strong>${signed(p.attempts.at(-1).sl)} SL</strong>을 누적했습니다. ${p.mode==='collaborate'?'각자 활동 1회':'활동 1회'} 소비.</p></div>`:''}${p.status==='ready'?`<div class="arcane-form-grid">${select('arcane-quality-'+p.id,'인상적인 성공이면 추가할 품질',Object.entries(A.ARCANE_QUALITIES),'Durable')}${select('arcane-flaw-'+p.id,'실패하면 추가할 결함',Object.entries(A.ARCANE_FLAWS),'Ugly')}</div><p class="note">완성 판정은 학문(마법) +0과 공예 +0입니다. 이때는 두 SL을 합산합니다.</p>${button('arcane-finish','완성 판정 · 결과 확정',`data-key="${esc(p.id)}"`,'primary')}`:''}${p.final?`<div class="arcane-last-roll">${roll(p.final.lore,'최종 학문(마법)')}${roll(p.final.trade,'최종 공예')}<p>최종 합계 <strong>${signed(p.final.sl)} SL</strong></p></div>`:''}${p.status==='awaiting-zero'?`<div class="callout"><strong>자료의 0 SL 경계가 겹칩니다</strong><p>주사위는 유지됩니다. GM 판정에 따라 두 결과 중 하나를 선택하세요.</p>${button('arcane-zero','근소한 성공 · 기간 +50%',`data-key="${esc(p.id)}" data-outcome="success"`)}${button('arcane-zero','근소한 실패 · 특이점 1개',`data-key="${esc(p.id)}" data-outcome="failure"`)}</div>`:''}${r?`<div class="arcane-result" role="status"><strong>${{masterpiece:'경이로운 성공 · 파괴 불가',quality:'인상적인 성공 · '+(A.ARCANE_QUALITIES[r.quality]||''),success:'문제 없이 완성',slow:'완성 · 제작 기간 50% 증가',quirk:'완성 · 특이점 1개',flawed:'완성 · 특이점 2개와 '+(A.ARCANE_FLAWS[r.flaw]||''),botch:'제작 실패 · 쓸모없는 결과물',explosion:'마법 폭발 · 폭탄과 동일한 타격'}[r.outcome]}</strong><p>${p.itemId?'완성품을 소지품에 추가했습니다. 장착하면 시트와 다음 전투에 연결됩니다.':r.outcome==='explosion'?'4판 코어 295쪽의 폭탄 타격을 GM이 적용해야 합니다. 완성품은 생성되지 않습니다.':'처음부터 새 작업으로 다시 제작해야 합니다.'}</p><small>제작 기간 ${A.arcaneTime(p)}</small>${r.quirks.map(q=>`<div class="arcane-quirk"><b>특이점·저주 ${q.rolls.map(t=>t.roll+(t.offset?' +'+t.offset:'')+' = '+t.total).join(' → ')}</b><p>${esc(q.text)}${q.days?' · 수명 '+q.days+'일':''}${q.sky?' · '+esc(q.sky):''}</p></div>`).join('')}${p.itemId?button('nav','소지품에서 장착','data-section="inventory"','primary'):''}</div>`:''}${p.attempts.length?`<details><summary>전체 제작 판정 기록</summary><ol class="arcane-history">${p.attempts.map((t,i)=>`<li>${i+1}회 · 학문 D100 ${t.lore.roll} / ${t.lore.target}: ${signed(t.lore.sl)} SL · 공예 D100 ${t.trade.roll} / ${t.trade.target}: ${signed(t.trade.sl)} SL → ${signed(t.sl)} SL · 누적 ${t.progress}</li>`).join('')}</ol></details>`:''}${['crafting','ready','awaiting-zero'].includes(p.status)?button('arcane-cancel','작업 중단',`data-key="${esc(p.id)}"`,'quiet'):''}</article>`;
  }).join(''):'<div class="empty">진행 중인 마법 제작 작업이 없습니다.</div>'+button('arcane-tab','새 제작 준비','data-key="prepare"','primary')}</div>`;
 }
 const table=(head,rows)=>`<div class="table-scroll"><table><thead><tr>${head.map(t=>`<th>${esc(t)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(t=>`<td>${esc(t)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
 function rulebook(){return `${check('arcane-college','소속 마법 대학에서 비전 마법을 배웠습니다 · GM 확인 (지팡이의 비전 주문 CN 보정)',state().archiveCollegeTrained)}<section class="block arcane-rules"><h2>제작 · 의뢰 · 입수</h2><p>${esc(A.ARCHIVE_REFERENCES.finding)}</p><p>모험 중 발견한 유물에 제작 판정을 강요하지 않습니다. 의뢰품은 적합한 전문가를 찾고 상담·의뢰 활동, 대가와 조건을 확인한 뒤 완성 판정을 합니다. 의뢰자가 결과물에 의견을 내는 방식도 원문에 존재합니다.</p><h3>직접·협력 제작</h3><ol><li>새 원재료부터 제작합니다. 기존 물품에 영구 마법을 더하지 않습니다.</li><li>학문(마법) −30과 희귀도별 공예 판정을 합니다. 두 결과 중 낮은 SL을 누적하며 보통 20 SL이 필요합니다.</li><li>협력자는 자신의 기술을 사용하고 양쪽 모두 제작 활동을 소비합니다.</li><li>완성할 때 두 기술을 +0으로 판정하고 SL을 합산합니다.</li></ol><p>원문은 최종 0 SL과 식별 0 SL을 성공·실패 양쪽에 포함합니다. 해당 결과는 주사위를 다시 굴리지 않고 GM이 확정합니다.</p>${table(['최종 SL','결과','효과'],A.ARCANE_RESULTS)}${table(['D100','유물 종류','참고 제작비','기간'],A.ARCANE_TYPES.map(t=>[t.range,t.name,t.cost,t.time===null?'합의':t.time+t.unit]))}<h3>입수품의 기록</h3><p>${esc(A.ARCHIVE_REFERENCES.history)}</p><p>발견한 갑옷은 원래 착용자의 종족과 체격을 각각 D10으로 정합니다. 플레이트의 맞음 여부, 큰 갑옷의 추가 운반량, 무기를 알아본 이들의 반응은 GM이 확인합니다.</p><p>${esc(A.ARCHIVE_REFERENCES.armour)}</p><p>${esc(A.ARCHIVE_REFERENCES.arrows)}</p><p>${esc(A.ARCHIVE_REFERENCES.scrolls)}</p><p>${esc(A.ARCHIVE_REFERENCES.staffs)}</p><p class="note">두루마리·반지의 주문은 현재 등록된 공식 마법 데이터에서 원문 최대 CN 규칙에 맞는 주문을 GM이 지정합니다. 해당 학파의 주문 자료가 없으면 임의 주문을 생성하지 않고 확정을 보류합니다. 기존 전투는 5판 환산 체계를 유지합니다.</p>${Object.entries(A.ARCHIVE_TABLES).map(([key,rows])=>`<details><summary>${esc(A.ARCANE_TYPES.find(t=>t.id===key)?.name)} 능력 D100 표</summary>${table(['D100','이름','효과'],rows.map(a=>[a.range,a.name,a.text]))}</details>`).join('')}<details><summary>발견한 무기의 역사</summary>${table(['D100','역사','효과'],A.ARCHIVE_HISTORY.map(h=>[h.range,h.name,h.text]))}</details><details><summary>특이점 · 저주</summary>${table(['범위','효과'],A.ARCANE_QUIRKS.map(q=>[q.min===q.max?q.min:q.min+'~'+q.max,q.text]))}</details><h3>임시 마법</h3><p>${esc(A.ARCHIVE_REFERENCES.temporary)} 홀수 굴림을 절반으로 한 결과의 처리는 원문에 명시되지 않았으므로 이 항목은 GM 참조 규칙으로 표시합니다.</p><p class="note">출처: ${esc(A.ARCANE_SOURCE)}. 실내·천체·명령어·신앙 등 조건과 전투 밖의 질병·사회적 효과는 GM 확인 기록을 사용합니다.</p></section>`;}
 function designPanel(v){const prefix='arcane',options=A.ARCANE_TYPES.map(t=>[t.id,t.name]),list=A.archiveBases(v.type);return `<section class="block arcane-order"><h2>새 유물 제작 설계</h2><div class="arcane-form-grid">${select('arcane-type','유물 종류',options,v.type)}<label>이름<input id="arcane-name" maxlength="300" value="${esc(v.name)}" placeholder="완성할 물품의 이름"></label>${list.length?select('arcane-base','새 물품의 기본 설계도',list.map(i=>[i.id,i.name+' · '+i.fields['핵심 수치']]),list.some(i=>i.id===v.baseId)?v.baseId:list[0]?.id):''}${select('arcane-mode','제작 방식',[['self','직접 제작'],['collaborate','파티 장인과 협력'],['commission','전문가에게 의뢰']],v.mode)}</div><p class="note">마법 능력을 원문 D100 표로 정합니다. 새 제작 작업에는 재료 퀘스트에서 얻은 작업권이 필요합니다.</p>${button('arcane-design-roll',v.design?'새 결과 굴리기':'원문 표로 유물 굴리기','','primary')}<span class="arcane-legendary-control">${button('arcane-legendary-roll','전설적 아이템이 나올 때까지 굴리기',['weapon','armour'].includes(v.type)?'':'disabled')}<small class="note">설계 결과만 정하며 제작 판정과 비용은 그대로 적용됩니다.</small></span>${v.design?designResult(v.design,prefix):'<div class="empty">원문 주사위 결과가 여기에 기록됩니다.</div>'}</section>`;}
 function designResult(d,prefix){return `<div class="arcane-design-result"><h3>${esc(d.base.name)} · ${esc(A.ARCANE_TYPES.find(t=>t.id===d.type)?.name)}</h3>${d.type==='weapon'?`<p>기본 무기 수치: ${esc(d.base.fields['핵심 수치'])}</p>`:''}${d.legendary?'<span class="pill">전설적 · 중복 없이 최대 5개</span>':''}${d.legendaryAttempts?`<p class="arcane-legendary-result" role="status">설계를 ${d.legendaryAttempts}회 굴려 전설적 결과를 얻었습니다. 아래는 마지막 설계의 실제 주사위 기록입니다.</p>`:''}${d.abilities.map(k=>{const a=A.ARCANE_ABILITIES.find(a=>a.id===k);return `<div class="arcane-quirk"><strong>${esc(a?.name||'D100 28 · GM 판정 대기')}</strong><p>${esc(a?.text||'불꽃 또는 죽음의 공포 중 원문 중복 범위를 확인하세요.')}</p></div>`}).join('')}${d.size?`<p>원래 착용자: ${esc(tr(d.size.species))} · ${esc(d.size.height)}</p>`:''}${d.creature?`<p>능력 적용 생물: <strong>${esc(d.creature.name)}</strong></p>`:''}${d.lore?`<p>학파 ${esc(tr(d.lore))}${d.maxCN!==undefined?' · 최대 CN '+d.maxCN:''}${d.spellId?' · '+esc(tr(rules().spells.find(s=>s.id===d.spellId)?.name||d.spellId)):''}</p>`:''}${d.effectiveType==='arrow'?`<p>원거리 무기 대신 백상검 능력의 탄약 ${d.quantity}발입니다.</p>`:''}${(d.history||[]).map(h=>`<p><b>무기 역사 · ${esc(h.name)}</b><br>${esc(h.text)}</p>`).join('')}${(d.quirks||[]).map(q=>`<p><b>특이점 · 저주</b><br>${esc(q.text)}${q.days?' · '+q.days+'일':''}</p>`).join('')}${d.pending.map(key=>{let options=[],label='';if(key==='weapon-28'){options=[['flame','불꽃 · 25~28'],['dolorous','죽음의 공포 · 28~31']];label='원문 중복값 28의 GM 결정';}else if(['gifted','material-conflict'].includes(key)){options=[['gromril','그롬릴'],['ithilmar','이실마르']];label='GM이 확인한 갑옷 재료';}else if(key==='spell'){options=A.archiveSpellCandidates(rules(),d).map(s=>[s.id,tr(s.name)+' · CN '+s.cn]);label='원문 CN 조건에 맞는 주문 · GM 결정';}else if(key==='history-quality'){options=Object.entries(A.ARCANE_QUALITIES);label='무기 역사로 얻는 품질';}else if(key==='history-flaw'){options=Object.entries(A.ARCANE_FLAWS).filter(([k])=>k!=='Bulky');label='무기 역사로 얻는 결함';}return `<div class="arcane-form-grid">${select(prefix+'-choice-'+key,label,[['','확인할 결과를 선택하세요'],...options],'')}${options.length?button('arcane-resolve-design','GM 결과 확정',`data-prefix="${prefix}" data-key="${key}"`):'<p class="note">현재 공식 주문 데이터에 해당 학파가 없습니다. 주문 자료가 확인될 때까지 확정을 보류합니다.</p>'}</div>`}).join('')}<details><summary>원문 주사위 기록 ${d.rolls.length}회</summary><ol class="arcane-history">${d.rolls.map(t=>`<li>${esc(t.table)} · D${t.die} ${t.roll}${t.ignored?' · '+esc(t.ignored):''}</li>`).join('')}</ol></details></div>`;}
 function acquire(){return `<section class="block"><h2>퀘스트 전리품</h2><p>의뢰 전투에서 승리한 뒤 보상 화면에서 발견 결과를 확정하세요. 획득한 유물은 아래 기록과 소지품에 반영됩니다.</p>${button('nav','퀘스트·보상으로','data-section="quests"','primary')}</section><section class="block"><h2>입수 내역</h2>${(state().magicAcquisitions||[]).slice().reverse().map(p=>`<article class="arcane-quirk"><strong>${esc(p.name)}</strong><p>${esc(p.note||'모험 중 입수')}</p><details><summary>입수 주사위 원본</summary>${designResult(p.design,'record-'+p.id)}</details></article>`).join('')||'<p>입수 기록이 없습니다.</p>'}${button('nav','소지품에서 장착','data-section="inventory"')}</section>`;}
 function identification(){return `<section class="block"><h2>마법 유물 식별 · 아카이브 2 52쪽</h2><p>보통 연구실·도서관 등 적절한 장소에서 시도마다 1주가 필요합니다. 학문(마법) +0 판정으로 능력과 특이점을 식별합니다. 유물 감지 재능은 접촉 후 직감 판정을 허용하므로 GM이 코어 재능 규칙으로 별도 확인하세요.</p>${table(['SL','식별 결과'],[['6 이상','능력과 모든 특이점 식별'],['4~5','능력 식별, 특이점 하나의 세부사항을 GM이 숨길 수 있음'],['2~3','능력과 눈에 보이는 특이점 식별'],['0~1','능력과 숨은 특이점 하나 식별'],['0~−1','식별 실패를 인지 · 눈에 보이는 특이점만'],['−2~−3','비슷한 다른 물품으로 오인'],['−4~−5','오인하고 없는 특이점 하나를 의심'],['−6 이하','오인하고 없는 특이점 둘 이상을 의심']])}${state().customItems.filter(i=>i.magicalArtifact).map(i=>{const a=i.magicalArtifact;return `<article class="arcane-quirk"><strong>${esc(i.name)}</strong><p>${a.identified?'능력 식별 완료':'능력 미식별 · GM이 공개할 정보를 확인하세요.'}</p>${button('arcane-identify','연구 1주 · 학문(마법) 판정',`data-key="${i.id}"`)}${a.identification?.at(-1)?`<p>D100 ${a.identification.at(-1).roll} · ${signed(a.identification.at(-1).sl)} SL · ${esc(a.identification.at(-1).note||'')}</p>`:''}${a.identification?.at(-1)?.pending?`${button('arcane-identify-zero','0 SL · 근소한 성공',`data-key="${i.id}" data-outcome="success"`)}${button('arcane-identify-zero','0 SL · 근소한 실패',`data-key="${i.id}" data-outcome="failure"`)}`:''}</article>`}).join('')}</section>`;}
 
 function readDraft(){
  for(const k of ['name','baseId','type','mode','trade','artisan','gold','silver','pennies','loreModifier','tradeModifier','expertName','expertLore','expertTrade','sbMultiplier','damage']){const el=$('arcane-'+(k==='baseId'?'base':k));if(el)draft[k]=el.value;}
  for(const k of ['fine','durable','verified','consulted','commissioned'])if($('arcane-'+k))draft[k]=!!$('arcane-'+k).checked;
  const checkboxes=document.querySelectorAll('[data-arcane-ability]');if(checkboxes.length)draft.abilities=[...checkboxes].filter(el=>el.checked).map(el=>el.dataset.arcaneAbility);
 }
 function action(name,el){const key=el.dataset.key;
  if(name==='arcane-tab'){readDraft();tab=key;ctx.render();return;}
  if(name==='arcane-legendary-roll'){readDraft();draft.design=A.rollArchiveLegendary(rules(),{type:draft.type,base:blueprint()});if(!draft.name)draft.name=draft.design.base.name;draft.abilities=draft.design.abilities;ctx.render();ctx.toast(draft.design.legendaryAttempts+'회 굴려 전설적 설계를 얻었습니다.');return;}
  if(name==='arcane-design-roll'){readDraft();draft.design=A.createArchiveDesign(rules(),{type:draft.type,base:blueprint(),found:false});if(!draft.name)draft.name=draft.design.base.name;draft.abilities=draft.design.abilities;ctx.render();return;}
  if(name==='arcane-resolve-design'){const v=draft;A.resolveArchiveChoice(rules(),v.design,key,$(el.dataset.prefix+'-choice-'+key)?.value);if(v===draft)v.abilities=v.design.abilities;ctx.render();return;}
  if(name==='arcane-new-day'){const a=state().customItems.find(i=>i.id===key)?.magicalArtifact;if(!a)throw Error('유물을 찾지 못했습니다.');a.dailyUsed={};a.elapsedDays++;ctx.render();return;}
  if(name==='arcane-identify'){A.identifyArchiveItem(rules(),state(),key);ctx.render();return;}
  if(name==='arcane-identify-zero'){A.resolveArchiveIdentification(state(),key,el.dataset.outcome);ctx.render();return;}
  if(name==='arcane-start'){
   readDraft();if(!draft.design)throw Error('원문 표로 유물 설계를 먼저 굴리세요.');const nums=[draft.gold,draft.silver,draft.pennies].map(Number);if(draft.gold===''||nums.some(n=>!Number.isSafeInteger(n)||n<0)||nums[1]>19||nums[2]>11)throw Error('실제 지급액을 골드·실버·페니로 입력하세요.');
   E.initMoney(rules(),state());const p=A.beginArcane(rules(),state(),{...draft,base:A.archiveBases(draft.type).find(i=>i.id===draft.baseId),costPennies:nums[0]*240+nums[1]*12+nums[2],loreModifier:Number(draft.loreModifier),tradeModifier:Number(draft.tradeModifier),expertLore:Number(draft.expertLore),expertTrade:Number(draft.expertTrade),artisan:artisan()});tab='projects';ctx.render();ctx.toast(p.status==='ready'?'의뢰를 기록했습니다. 완성 판정을 진행하세요.':'제작을 준비했습니다. 활동 판정으로 20 SL을 누적하세요.');return;
  }
  if(name==='arcane-quote'){readDraft();const n=quote();if(n===null)throw Error('이 물품은 별도 가격 합의가 필요합니다.');draft.gold=Math.floor(n/240);draft.silver=Math.floor(n%240/12);draft.pennies=n%12;ctx.render();return;}
  if(name==='arcane-roll'){A.advanceArcane(rules(),state(),key);ctx.render();ctx.toast('두 판정 중 낮은 SL을 누적했습니다.');return;}
  if(name==='arcane-finish'||name==='arcane-zero'){const result=A.finishArcane(rules(),state(),key,name==='arcane-zero'?{zeroOutcome:el.dataset.outcome}:{quality:$('arcane-quality-'+key)?.value,flaw:$('arcane-flaw-'+key)?.value});ctx.render();ctx.toast(result.pending?'합계 0 SL입니다. GM 판정에 따라 결과를 선택하세요.':['botch','explosion'].includes(result.outcome)?'마법 제작의 실패 결과를 확인하세요.':'마법 유물을 완성해 소지품에 추가했습니다.');return;}
  if(name==='arcane-cancel'){ctx.confirm('제작 작업 중단','이미 사용한 재료와 비용은 반환되지 않습니다.',()=>{A.cancelArcane(state(),key);ctx.render();});return;}
 }
 function change(el){
  if(el.id==='arcane-college'){state().archiveCollegeTrained=!!el.checked;ctx.render();return true;}
  if(el.dataset.arcaneItem){const item=state().customItems.find(i=>i.id===el.dataset.arcaneItem),a=item?.magicalArtifact;if(!a)throw Error('마법 유물을 찾지 못했습니다.');const k=el.dataset.arcaneSetting;if(k==='attachedTo'){a.attachedTo=String(el.value).slice(0,200);}else if(k==='elapsedDays'||k==='charges'){const n=Number(el.value);if(!Number.isSafeInteger(n)||n<0||n>1000000)throw Error('경과일은 0 이상의 정수로 입력하세요.');a[k]=n;}else if(['active','conditionsMet'].includes(k))a[k]=!!el.checked;A.validateArcaneArtifact(a);ctx.render();return true;}
  if(el.id?.startsWith('arcane-quality-')||el.id?.startsWith('arcane-flaw-'))return true;
  if(el.id?.includes('-choice-'))return true;
  if(el.id?.includes('-choice-'))return true;
  if(!el.id?.startsWith('arcane-')&&!el.dataset.arcaneAbility)return false;const oldMode=draft.mode;readDraft();if(['arcane-type','arcane-base'].includes(el.id)){draft.design=null;draft.sbMultiplier='';draft.damage='';}if(['arcane-sbMultiplier','arcane-damage'].includes(el.id)&&draft.design)draft.design.base=blueprint();if(oldMode!==draft.mode&&draft.mode==='commission'){draft.fine=true;draft.durable=true;}if(el.id==='arcane-base'){const item=A.archiveBases(draft.type).find(i=>i.id===draft.baseId);draft.tradeModifier=A.ARCANE_DIFFICULTIES[item?.fields['등급']]??0;}ctx.render();return true;
 }
