for(const base of [...ENEMY_PROFILES].filter(p=>['human','goblin','orc','clanrat','cultist','chaos-warrior','bloodletter','daemonette','plaguebearer','pink-horror','blue-horror'].includes(p.id))){
 const p=JSON.parse(JSON.stringify(base));p.id=base.id+'-swarm';p.name=base.name+' 무리';p.maxWounds*=5;p.stats.WS+=10;for(const k of Object.keys(p.skills))if(k.startsWith('Melee'))p.skills[k]+=10;p.traits={...p.traits,Swarm:1};p.swarmMembers=5;p.baseProfileId=base.id;p.footprintSize='Large';p.source={...base.source,note:'기본 시트는 유지하고 4판 코어342쪽 Swarm 특성을 추가한 퀘스트용 무리입니다. 지능 있는 병사에게 적용하는 것은 사용자 지정 확장입니다. 다섯 명을 한 참가자로 처리합니다. 2×2칸은 표시용이며 크기 전투 보정은 없습니다.'};ENEMY_PROFILES.push(p);
}

