function matchesTarget(target,type){if(!type)return false;const aliases={'그린스킨':'greenskins','악마':'daemons','드워프':'dwarfs','엘프':'elves','인간':'humans','생물':'living','모든 것':'everything'};type=aliases[type]||type;let t=String(type).toLowerCase();if(t==='everything')return true;if(['living','living things'].includes(t))return isLiving(target);return [target.id,target.name,target.species,target.faction,trait(target,'Daemonic')?'daemons':'',trait(target,'Spellcaster')?'wizards':''].some(x=>String(x).toLowerCase().includes(t)||norm(x)===norm(type))}
