   if(!airborne&&n>1&&dx&&dy&&[...occupiedCells({...point,x:at.x}),...occupiedCells({...point,y:at.y})].some(c=>walls.has(c.x+','+c.y)||occupied.has(c.x+','+c.y)))continue;
   if(foes.some(t=>distance(t,point)>distance(t,a)))continue;
