function spellMeasure(value){return String(value||'즉시').replace(/WPB|IB|SB|TB|AB|FB|WP|Int|You|Self|Instant|Special|Rounds?|Minutes?|Hours?|Days?|yards|×|x(?=\d)/gi,key=>({wpb:'의지 보너스',ib:'지능 보너스',sb:'근력 보너스',tb:'강인함 보너스',ab:'민첩성 보너스',fb:'사교성 보너스',wp:'의지',int:'지능',you:'자신',self:'자신',instant:'즉시',special:'특수',round:'라운드',rounds:'라운드',minute:'분',minutes:'분',hour:'시간',hours:'시간',day:'일',days:'일',yards:'야드',x:'×'})[key.toLowerCase()]||key);}
