 const w=weaponOf(a,o.weaponId)||weaponOf(a),sp=spellFor(a,o.spellId),tech=E.SWORD_TECHNIQUES.find(t=>t.id===o.techniqueId);let name=D.ACTION_NAMES[action]||action,text=ACTION_EFFECTS[action]||'',formula='',meta=[];
