  const deaths=entries.filter(e=>e.kind==='death'&&e.actor&&e.position).map(e=>({n:e.n,round:e.round,kind:'visual',actor:e.actor,name:e.name,team:e.team,action:'death',terminalState:e.state,label:e.state==='banished'?'소멸':'사망',outcome:e.reason,from:e.position,to:e.position,target:e.actor,targetName:e.name,dice:[],terminalLog:e.n}));
