  const totals=new Map;for(const s of actions)for(const x of sceneLosses(s))totals.set(x.actor,(totals.get(x.actor)||0)+x.amount);
  const extra=(states?.after||[]).flatMap(a=>{const before=states.before.find(x=>x.id===a.id);const amount=before?before.wounds-a.wounds-(totals.get(a.id)||0):0;return amount?[{actor:a.id,name:b.actors.find(x=>x.id===a.id)?.name,amount,position:{x:a.x,y:a.y,size:a.size},maxWounds:a.maxWounds}]:[];});
  if(extra.length&&actions.length){const primary=actions.findLast(s=>s.action!=='riposte')||actions[0],rows=new Map(sceneLosses(primary).map(x=>[x.actor,{...x}]));for(const x of extra){const row=rows.get(x.actor);if(row)row.amount+=x.amount;else rows.set(x.actor,x);}primary.losses=[...rows.values()].filter(x=>x.amount!==0);}
