 const path=movementPath(scene).map(v=>p({...v,size:v.size||actor?.size})),points=path.map(x=>`${x.x},${x.y}`).join(' '),d=path.map((x,i)=>`${i?'L':'M'}${x.x},${x.y}`).join(' ');
 const impactPhase=scene.phase==='impact',effectPhase=scene.phase==='effect',moving=type==='move',linked=!impactPhase&&scene.actor!==scene.target&&!moving&&['attack','ranged','cast','technique','breath'].includes(type);
 let trace=moving?`<polyline class="fx-movement-trail" points="${points}" marker-end="url(#battle-arrow)"/>${animate?`<circle class="fx-moving-token" r="8"><animateMotion dur="${(scene.motionDuration??movementDuration(scene,b.config.playback||'normal'))/1000}s" path="${d}" fill="freeze"/></circle>`:''}`:linked?`<path class="fx-action-line ${type}" d="M${start.x},${start.y}L${end.x},${end.y}"/>${animate?`<circle class="fx-projectile" r="${type==='cast'||type==='breath'?12:6}"><animateMotion dur=".65s" path="M${start.x},${start.y}L${end.x},${end.y}" fill="freeze"/></circle>`:''}`:'';
