 const role=action==='channel'?'channel':/armour|armor|shield|ward|protection|pelt|shroud|aegis/.test(id)?'barrier':/heal|lifebloom|earthblood|regener|heart|cure/.test(id)?'healing':/flight|teleport|bridge|mirkride|shadowsteed/.test(id)?'travel':/fear|curse|treason|acquiescence|languish|tangle|net-|mind|caress|soul/.test(id)?'curse':'attack';
