const Q=(()=>{
const clone=x=>JSON.parse(JSON.stringify(x)),now=()=>new Date().toISOString(),id=()=>globalThis.crypto?.randomUUID?.()||'quest-'+Date.now()+'-'+Math.random().toString(36).slice(2);
const stages=['preparation','ready','combat','reward','pursuit-ready','pursuit-combat','restitution','atonement-ready','atonement-combat'];
function ensure(s){
 if(!s.campaign){s.campaign={version:1,active:null,runs:[],completed:[],trust:{human:0,dwarf:0,elf:0,wood:0,halfling:0},dwarfGrudge:false,materials:{rune:0,magic:0,ledger:[]}};for(const p of [...(s.runeProjects||[]),...(s.magicCraftProjects||[])])p.materialPermit??='legacy';}
 const c=s.campaign;
 if(c.version!==1||!Array.isArray(c.runs)||c.runs.length>1000||!Array.isArray(c.completed)||c.completed.some(k=>!QUEST_CATALOG.list.some(q=>q.id===k))||!c.trust||typeof c.dwarfGrudge!=='boolean'||!c.materials||!['rune','magic'].every(k=>Number.isSafeInteger(c.materials[k])&&c.materials[k]>=0&&c.materials[k]<=1000000)||!Array.isArray(c.materials.ledger)||c.materials.ledger.length>4000)throw Error('퀘스트·재료 기록이 잘못되었습니다.');
 for(const k of ['human','dwarf','elf','wood','halfling'])if(!Number.isSafeInteger(c.trust[k])||Math.abs(c.trust[k])>100000)throw Error('신뢰 기록이 잘못되었습니다.');
 if(c.active&&(!QUEST_CATALOG.list.some(q=>q.id===c.active.questId)||!stages.includes(c.active.stage)||typeof c.active.id!=='string'||!Number.isInteger(c.active.seed)||!c.active.checks||!Array.isArray(c.active.battles)||!Array.isArray(c.active.participants)||!Array.isArray(c.active.encounter)||c.active.encounter.some(([k,n])=>!D.ENEMY_PROFILES.some(p=>p.id===k)||!Number.isInteger(n)||n<1||n>24)))throw Error('진행 중인 퀘스트 기록이 잘못되었습니다.');
 return c;
}
function spend(s,kind,projectId){const c=ensure(s);if(!['rune','magic'].includes(kind)||!c.materials[kind])throw Error((kind==='rune'?'룬스미싱':'마법 제작')+' 재료가 없습니다. 재료 수집 퀘스트에서 작업권을 확보하세요.');c.materials[kind]--;c.materials.ledger.push({kind,amount:-1,projectId,at:now()});return projectId;}
function requireMaterial(s,kind){if(!ensure(s).materials[kind])throw Error('재료 수집 퀘스트를 완료해 '+(kind==='rune'?'각인':'마법 제작')+' 작업권을 확보하세요.');}
function grantMaterials(s,kind,n,runId){const c=ensure(s);c.materials[kind]+=n;c.materials.ledger.push({kind,amount:n,runId,at:now()});}
function def(run){return QUEST_CATALOG.list.find(q=>q.id===(typeof run==='string'?run:run.questId));}
function block(s,q){const c=ensure(s);if(!s.finalized)return '캐릭터 생성을 먼저 완료하세요.';if(c.active)return '진행 중인 퀘스트를 먼저 마치세요.';if(c.dwarfGrudge&&q.faction==='dwarf')return '드워프의 원한: 가보 반환과 고블린 청소로 용서받아야 합니다.';if(!q.repeat&&c.completed.includes(q.id))return '이미 완료한 사건입니다.';const missing=(q.requires||[]).filter(k=>!c.completed.includes(k));if(missing.length)return '선행 사건: '+missing.map(k=>def(k).name).join(' → ');return '';}
function pack(rows){return rows.flatMap(([key,n])=>{const swarm=D.ENEMY_PROFILES.find(p=>p.id===key+'-swarm');if(n>=5&&swarm){const groups=Math.floor(n/5),remainder=n%5;return [[swarm.id,groups],...(remainder?[[key,remainder]]:[])];}return [[key,n]];});}
function accept(s,key){const q=def(key);if(!q)throw Error('퀘스트를 찾지 못했습니다.');const reason=block(s,q);if(reason)throw Error(reason);const c=ensure(s);if(c.runs.length>=999)throw Error('퀘스트 기록 한도에 도달했습니다. 백업 후 새 캠페인을 시작하세요.');const run={id:id(),questId:key,stage:'preparation',seed:E.die(1000000000),checks:{},battles:[],participants:[],encounter:pack(q.enemies),background:q.background,at:now(),owner:E.characterId(s),nonce:null};c.active=run;return run;}
function draw(run,n=100){run.seed=(Math.imul(run.seed,1664525)+1013904223)>>>0;return run.seed%n+1;}
function skills(r,s,phase,run=ensure(s).active){if(!run)return [];const q=def(run),allowed=phase==='escape'?['Stealth','Bribery','Sleight of Hand']:q[phase==='prep'?'prep':'reward'];const ranks=E.skillRanks(s);let keys=[...allowed.filter(k=>E.skillInfo(r,k)&&!E.skillInfo(r,k).grouped),...Object.keys(ranks).filter(k=>allowed.some(t=>E.base(t)===E.base(k)))];return [...new Set(keys.map(k=>E.resolve(s,k)))].filter(k=>{const info=E.skillInfo(r,k);return info&&(info.basic||ranks[k]>0)&&!/\(Any\)$/.test(k)&&!(['Melee','Ranged','Channelling','Runesmithing'].includes(E.base(k)));});}
function score(r,s,key){const info=E.skillInfo(r,key),ranks=E.skillRanks(s);if(!info||!info.basic&&!(ranks[key]>0))throw Error('해당 고급 기술을 먼저 습득하세요.');return E.characteristics(s)[E.STATS.indexOf(info.stat)]+(ranks[key]||0)*5;}
function talentBonuses(r,s,key){return [...new Set(E.selectedTalents(s))].flatMap(k=>{const t=E.talentInfo(r,k),tests=String(t?.tests||'');const b=E.base(key);return tests&&(tests.toLowerCase().includes(key.toLowerCase())||tests.toLowerCase().includes(b.toLowerCase()))?[{key:k,rank:E.rank(s,k)}]:[];});}
function check(r,s,actor,key,phase,{roll}={}){const run=ensure(s).active;if(!run)throw Error('진행 중인 퀘스트가 없습니다.');const required=phase==='prep'?'preparation':phase==='reward'?'reward':'reward';if(run.stage!==required||run.checks[phase])throw Error('이 단계의 판정은 퀘스트당 한 번만 가능합니다.');if(phase==='escape'&&!def(run).heirloom)throw Error('가보를 숨길 때만 사용할 수 있습니다.');if(!skills(r,actor,phase,run).includes(key))throw Error('시트에 있는 해당 단계의 비전투 기술을 선택하세요.');const bonuses=talentBonuses(r,actor,key),t=C.rollTest(score(r,actor,key),roll??draw(run),QUEST_CATALOG.tier[def(run).difficulty].sl);if(t.success)t.sl+=bonuses.reduce((n,x)=>n+x.rank,0);const out={...t,key,actorId:E.characterId(actor),actor:actor.profile.name||'이름 없는 모험가',talents:t.success?bonuses:[],at:now()};run.checks[phase]=out;return out;}
function skipPrep(s){const run=ensure(s).active;if(run?.stage!=='preparation')throw Error('준비 단계가 아닙니다.');run.stage='ready';}
function booking(s){const run=ensure(s).active;if(!run||!['ready','pursuit-ready','atonement-ready'].includes(run.stage))throw Error('이 퀘스트의 전투를 준비할 수 없습니다.');return {owner:run.owner,runId:run.id,stage:run.stage,nonce:run.nonce|| (run.nonce=id()),encounter:clone(run.encounter),background:run.background};}
function startBattle(s,b,party){const run=ensure(s).active,link=b.config.questLink;if(!run||!link||run.id!==link.runId||run.owner!==link.owner||run.nonce!==link.nonce||run.stage!==link.stage)throw Error('진행 중인 퀘스트와 전투 연결이 일치하지 않습니다.');const expected=run.encounter.flatMap(([k,n])=>Array(n).fill(k)).sort(),actual=b.actors.filter(a=>a.team==='enemies').map(a=>a.profileId).sort();if(JSON.stringify(expected)!==JSON.stringify(actual))throw Error('퀘스트 적 편성은 고정되어 있습니다.');const members=[...new Set(b.actors.filter(a=>a.team==='allies'&&!a.riderId).map(a=>party[Number(a.id.replace('ally-',''))]?.state).filter(Boolean).map(E.characterId))];if(!members.includes(run.owner))throw Error('의뢰를 받은 캐릭터를 파티에 포함하세요.');run.participants=members;run.stage=link.stage.replace('ready','combat');run.battleSeed=b.initialSeed;run.battleNonce=link.nonce;return run;}
function finalizeRun(s,status,note){const c=ensure(s),run=c.active;c.runs.push({...clone(run),status,note,finishedAt:now()});if(status==='completed'&&!c.completed.includes(run.questId))c.completed.push(run.questId);c.active=null;return c.runs.at(-1);}
function observe(s,b,r){const c=ensure(s),run=c.active,link=b?.config?.questLink;if(!run||!link||!['finished','draw'].includes(b.status)||run.id!==link.runId||run.owner!==link.owner||run.battleNonce!==link.nonce||run.battleSeed!==b.initialSeed||!run.stage.endsWith('combat')||run.battles.some(x=>x.nonce===link.nonce))return false;
 run.battles.push({nonce:link.nonce,winner:b.winner,round:b.round,at:now()});run.nonce=null;
 if(b.winner!=='allies'){
  if(run.stage==='pursuit-combat'){run.stage='restitution';run.dialogue='도망칠 셈이었나, 움기? 우리 가보를 내려놔라. 살고 싶으면 훔친 물건부터 돌려줘.';}
  else if(run.stage==='atonement-combat'){run.stage='atonement-ready';run.dialogue='고블린 몇 놈도 못 치우고 돌아왔나? 말로는 원한을 지울 수 없다. 다시 가라.';}
  else finalizeRun(s,'failed',b.winner==='draw'?'시간 제한·무승부: 보상 없음':'전투 패배: 보상 없음');
 }else if(run.stage==='pursuit-combat'){run.stage='restitution';run.dialogue='우릴 쓰러뜨렸다고 네 도둑질이 없어지는 줄 아나? 가보를 돌려줘라. 그다음 고블린을 치워. 그 전엔 우리 일을 맡길 생각 마라.';}
 else if(run.stage==='atonement-combat'){c.dwarfGrudge=false;c.trust.dwarf=Math.max(0,c.trust.dwarf);finalizeRun(s,'atoned','가보 반환과 고블린 청소 완료 · 드워프 원한 해제. “이번 한 번은 원한장에서 지운다. 다시 손대면 끝이다, 움기.”');}
 else{run.stage='reward';run.dialogue='임무를 마쳤습니다. 비전투 능력을 활용하고 보상 선택지를 고르세요.';preview(s,r);}
 return true;
}
function bonus(s){const run=ensure(s).active;return Math.min(8,['prep','reward'].reduce((n,k)=>n+(run?.checks[k]?.success?Math.min(5,Math.max(1,run.checks[k].sl)):0),0));}
function preview(s,r={spells:D.CORE_SPELLS}){const run=ensure(s).active;if(!run||run.stage!=='reward')throw Error('승리 후에 보상을 확인할 수 있습니다.');if(run.preview)return run.preview;const q=def(run),tier=QUEST_CATALOG.tier[q.difficulty],n=draw(run);let loot=null;if(!q.heirloom&&n<=tier.loot){const kind=draw(run,100),high=['high','world'].includes(q.difficulty);if(high&&kind<=45){const design=A.createArchiveDesign(r,{type:'weapon',found:true,draw:n=>draw(run,n)});loot={kind:'magic',design};}else if(kind<=75){const base=CATALOG.resolveItemSpec(q.faction==='dwarf'?'Dwarf Axe':'Hand Weapon')||A.archiveBases('weapon')[0];loot={kind:'rune',item:clone(base),runes:q.difficulty==='world'?[1,3,8]:q.difficulty==='high'?[1,3]:[1]};}else{const pool=CATALOG.ITEMS.filter(i=>!i.zones.length&&i.category==='방어구'&&/^그롬릴/.test(i.name));const item=pool[draw(run,pool.length)-1];if(item)loot={kind:'catalog',item:clone(item)};}}
 run.preview={roll:n,chance:tier.loot,loot};return run.preview;}
function addItem(s,item,runId){const v=clone(item);v.id='custom-quest-'+id();v.craftType??=v.category==='방어구'?'metal':v.category==='무기'?'melee':'other';v.fields=Object.fromEntries(Object.entries(v.fields||{}).map(([k,x])=>[k,x==null?'':String(x)]));v.questReward={runId,at:now()};v.zones=[];v.pricePennies=null;v.fields={...v.fields,'입수 기록':'퀘스트 '+runId,'상점판매':'불가 · 퀘스트 보상'};E.createCustomItem(s,v);return v;}
function deliverLoot(r,s,run){const loot=run.preview?.loot;if(!loot)return null;if(loot.kind==='magic'){if(loot.design.pending.length)throw Error('유물 원문의 미확정 결과를 먼저 선택하세요.');const item=A.acquireArchiveItem(r,s,{name:'발견한 '+loot.design.base.name,design:loot.design,verified:true,identified:true,note:def(run).name+' · 퀘스트 전리품'});item.questReward={runId:run.id,at:now()};return item;}
 const item=addItem(s,loot.item,run.id);if(loot.kind==='rune'){item.name='고대 룬 '+item.name;item.fields['한글명']=item.name;s.runeItems[item.id]=[...loot.runes];}return item;}
function heirloom(s){const run=ensure(s).active;if(run.heirloomKey)return;const base=CATALOG.resolveItemSpec('Dwarf Axe')||A.archiveBases('weapon')[0],item=addItem(s,base,run.id);item.name='드워프 가문의 룬 도끼';item.fields['한글명']=item.name;item.fields['입수 기록']='반환 의뢰를 받은 가보';s.runeItems[item.id]=[1,3];run.heirloomKey=item.id;}
function removeHeirloom(s,run){s.customItems=s.customItems.filter(i=>i.id!==run.heirloomKey);s.equipped=s.equipped.filter(k=>k!==run.heirloomKey);delete s.runeItems[run.heirloomKey];delete s.itemSpecs[run.heirloomKey];}
function keep(s){const c=ensure(s),run=c.active;if(run?.stage!=='reward'||!def(run).heirloom)throw Error('가보 보상 선택 단계가 아닙니다.');heirloom(s);const escaped=run.checks.escape,chance=Math.max(5,35-(escaped?.success?Math.max(1,escaped.sl)*5:0)),n=draw(run);run.discovery={roll:n,chance};
 if(n>chance){return finalizeRun(s,'failed','미발각: 가보 보유 · 골드와 임무 XP 없음. “빈손으로 돌아와? 그걸 변명이라고 하나, 움기. 보수는 없다. 썩 꺼져라.”');}
 c.dwarfGrudge=true;c.trust.dwarf=Math.min(-5,c.trust.dwarf-5);run.stage='pursuit-ready';run.encounter=[['dwarf',2]];run.dialogue='멈춰라, 움기! 그 도끼가 어디서 났는지 모를 줄 알았나? 가보를 내려놔. 네 손목을 자르기 전에!';return run;
}
function returnStolen(s){const c=ensure(s),run=c.active;if(run?.stage!=='restitution')throw Error('추격전을 마친 뒤 가보를 반환하세요.');removeHeirloom(s,run);run.stage='atonement-ready';run.encounter=[['goblin',3]];run.background='underground';run.dialogue='돌려줬다고 끝인 줄 아나, 움기? 아래 갱도의 고블린부터 치워라. 피로 갚고 와야 원한장을 다시 펼쳐보겠다.';return run;}
function award(s,xp,gold,runId){if(!Number.isSafeInteger(xp)||xp<0||!Number.isSafeInteger(gold)||gold<0)throw Error('보상 수치를 확인하세요.');s.xp+=xp;s.xpEarned+=xp;if(gold){s.goldPennies+=gold;s.moneyHistory.push({kind:'grant',amount:gold,quest:runId,at:now()});}s.history.push({kind:'quest-xp',key:String(xp),quest:runId,cost:0,at:now()});}
function claim(r,s,choice,recipients=[]){const c=ensure(s),run=c.active;if(run?.stage!=='reward')throw Error('보상은 승리한 퀘스트당 한 번만 받을 수 있습니다.');const q=def(run),tier=QUEST_CATALOG.tier[q.difficulty],b=bonus(s),choices=q.material?['materials','sell']:q.heirloom?['return']:q.choices.map(x=>x.id);if(!choices.includes(choice))throw Error('해당 임무의 보상 선택지를 고르세요.');const xp=Math.round(tier.xp*(1+b*.05)),fullGold=tier.gold*240+Math.round(tier.gold*240*b*.1),gold=choice==='trust'?Math.floor(fullGold/2):choice==='materials'?Math.floor(fullGold/2):fullGold;const loot=deliverLoot(r,s,run);
 const all=[s,...recipients].filter(v=>v?.finalized&&run.participants.includes(E.characterId(v))),seen=new Set();for(const v of all){const key=E.characterId(v);if(seen.has(key))continue;seen.add(key);award(v,xp,key===run.owner?gold:0,run.id);}
 let credits=0;if(q.material&&choice==='materials'){credits=tier.credits+(b>=3?1:0);grantMaterials(s,q.material,credits,run.id);}c.trust[q.faction]+=(q.heirloom?2:choice==='trust'?2:1);
 run.result={xpPerMember:xp,goldPennies:gold,material:q.material||null,credits,loot:loot?.name||null,choice,members:[...seen],effect:q.effect||null};return finalizeRun(s,'completed',q.heirloom?'가보 반환 · 신뢰 +2. “가보는 돌아왔군. 늦었지만 약속은 지켰어. 이건 네 보수다. 가문의 보물에 견줄 생각은 마라.”':q.effect||'의뢰 완료');}
function abandon(s){const run=ensure(s).active;if(!run)throw Error('진행 중인 임무가 없습니다.');return finalizeRun(s,'abandoned','의뢰 포기: 보상 없음 · 사용한 재료와 원한은 유지됩니다.');}
return {ensure,spend,requireMaterial,grantMaterials,def,block,pack,accept,draw,skills,score,talentBonuses,check,skipPrep,booking,startBattle,observe,preview,bonus,claim,keep,returnStolen,abandon};})();

const originalEnemyPreset=D.enemyPreset;D.enemyPreset=(...args)=>Q.pack(originalEnemyPreset(...args));

export {CREATION_GUIDE,E,I18N,GEAR,CATALOG,V,X,A,AU,D,L,P,MOUNTS,C,F,QUEST_CATALOG,Q};
